import { DateInputForm } from '@/components/forms/DateInputForm';
import SelectInputForm from '@/components/forms/SelectInputForm';
import SmallImgInputForm from '@/components/forms/SmallImgInputForm';
import TextInputForm from '@/components/forms/TextInputForm';

interface Props {
    personalImage?: string | null;
}

const PROGRAM_OPTIONS = [
    { value: 'it', name: 'تقنية المعلومات' },
    { value: 'business', name: 'إدارة أعمال' },
    { value: 'engineering', name: 'هندسة' },
    { value: 'finance', name: 'مالية ومحاسبة' },
];

const SUPERVISOR_OPTIONS = [
    { value: 'ahmed', name: 'أحمد الشمري' },
    { value: 'sara', name: 'سارة العتيبي' },
    { value: 'khalid', name: 'خالد الغامدي' },
];

const WEEKS_OPTIONS = Array.from({ length: 24 }, (_, i) => ({
    value: String(i + 1),
    name: String(i + 1),
}));

export default function TrainingData({ personalImage }: Props) {
    return (
        <div className="mb-6 grid grid-cols-1 gap-6 md:grid-cols-[1fr_1fr_200px]">
            <div className="flex flex-col gap-4">
                <SelectInputForm
                    name="training_program"
                    label="البرنامج التدريبي"
                    options={PROGRAM_OPTIONS}
                    placeholder="تقنية المعلومات"
                />
                <DateInputForm name="training_start_date" label="تاريخ البدء" placeholder="mm/dd/yyyy" />
                <TextInputForm
                    name="training_hours"
                    label="ساعات التدريب"
                    placeholder="40"
                    type="text"
                    className="[&>input]:text-end [&>input]:placeholder:text-end"
                />
            </div>
            <div className="flex flex-col gap-4">
                <SelectInputForm
                    name="direct_supervisor"
                    label="المشرف المباشر"
                    options={SUPERVISOR_OPTIONS}
                    placeholder="أحمد الشمري"
                />
                <DateInputForm name="training_end_date" label="تاريخ الانتهاء" placeholder="mm/dd/yyyy" />
                <SelectInputForm
                    name="weeks_count"
                    label="عدد الأسابيع"
                    options={WEEKS_OPTIONS}
                    placeholder="اختر عدد الأسابيع"
                />
            </div>
            <div className="flex flex-col">
                {personalImage ? (
                    <SmallImgInputForm
                        name="personal_image"
                        maxSize={50 * 1024 * 1024}
                        multiple={false}
                        label="الصورة الشخصية"
                        editImages={personalImage}
                    />
                ) : (
                    <SmallImgInputForm
                        name="personal_image"
                        maxSize={50 * 1024 * 1024}
                        multiple={false}
                        label="الصورة الشخصية"
                    />
                )}
                <p className="mt-2 text-xs leading-relaxed text-[#90868C] text-start">
                    الملفات المسموح بها: jpg، png، pdf. أقصى حجم 50MB
                </p>
            </div>
        </div>
    );
}
