import { z } from 'zod';

const MAX_CERT_SIZE = 10 * 1024 * 1024;
const MAX_PROFILE_SIZE = 50 * 1024 * 1024;
const IMG_TYPES = ['image/jpeg', 'image/png', 'image/jpg', 'image/gif', 'image/svg+xml'];

const fileOrString = z.union([z.instanceof(File), z.string()]).optional();

export const AddTraineeSchema = z
    .object({
        name: z.string().min(1, 'الاسم مطلوب'),
        address: z.string().min(1, 'العنوان مطلوب'),
        id_number: z.string().min(1, 'رقم الهوية مطلوب'),
        birth_date: z.date({ required_error: 'تاريخ الميلاد مطلوب' }),
        phone_number: z
            .string()
            .min(1, 'رقم الهاتف مطلوب')
            .refine((val) => /^\d+$/.test(val), 'الرجاء إدخال أرقام فقط')
            .refine((val) => val.length >= 8 && val.length <= 15, 'يجب أن يتكون رقم الهاتف من 8 إلى 15 رقم'),
        email: z.string().min(1, 'البريد الإلكتروني مطلوب').email('بريد إلكتروني غير صالح'),

        education_degree: z.string().min(1, 'المؤهل العلمي مطلوب'),
        university: z.string().min(1, 'الجامعة مطلوبة'),
        specialization: z.string().min(1, 'التخصص مطلوب'),
        graduation_year: z.string().min(1, 'سنة التخرج مطلوبة'),
        skills: z.string().optional().nullable(),
        previous_experience: z.string().optional().nullable(),

        degree_certificate: fileOrString,

        training_program: z.string().min(1, 'البرنامج التدريبي مطلوب'),
        direct_supervisor: z.string().min(1, 'المشرف المباشر مطلوب'),
        training_start_date: z.date({ required_error: 'تاريخ البدء مطلوب' }),
        training_end_date: z.date({ required_error: 'تاريخ الانتهاء مطلوب' }),
        training_hours: z.string().min(1, 'ساعات التدريب مطلوبة'),
        weeks_count: z.string().min(1, 'عدد الأسابيع مطلوب'),

        personal_image: fileOrString,
    })
    .superRefine((data, ctx) => {
        if (data.training_end_date < data.training_start_date) {
            ctx.addIssue({
                code: 'custom',
                message: 'تاريخ الانتهاء يجب أن يكون بعد تاريخ البدء',
                path: ['training_end_date'],
            });
        }
        const hours = Number(data.training_hours);
        if (!Number.isFinite(hours) || hours <= 0) {
            ctx.addIssue({
                code: 'custom',
                message: 'أدخل عدد ساعات صالحاً',
                path: ['training_hours'],
            });
        }
    })
    .superRefine((data, ctx) => {
        const hasPersonal =
            data.personal_image instanceof File ||
            (typeof data.personal_image === 'string' && data.personal_image.length > 0);
        if (!hasPersonal) {
            ctx.addIssue({
                code: 'custom',
                message: 'الصورة الشخصية مطلوبة',
                path: ['personal_image'],
            });
        }
        const checkFile = (val: unknown, path: 'personal_image' | 'degree_certificate', max: number, label: string) => {
            if (val instanceof File) {
                if (val.size > max) {
                    ctx.addIssue({ code: 'custom', message: `${label}: أقصى حجم ${max / 1024 / 1024}MB`, path: [path] });
                }
                if (path === 'personal_image' && !IMG_TYPES.includes(val.type)) {
                    ctx.addIssue({ code: 'custom', message: 'صيغة الملف غير مدعومة', path: [path] });
                }
            }
        };
        checkFile(data.personal_image, 'personal_image', MAX_PROFILE_SIZE, 'الصورة الشخصية');
        checkFile(data.degree_certificate, 'degree_certificate', MAX_CERT_SIZE, 'الشهادة');
    });

export type AddTraineeFormValues = z.infer<typeof AddTraineeSchema>;
