import { cn } from '@/lib/utils';
import { Check } from 'lucide-react';

type Step = 1 | 2;

interface Props {
    step: Step;
}

const steps: {
    id: Step;
    title: string;
    subtitle: string;
    num: string;
}[] = [
        { id: 1, title: 'البيانات الشخصية والمؤهلات', subtitle: 'تفاصيل الشخصية', num: '01' },
        { id: 2, title: 'بيانات التدريب', subtitle: 'تفاصيل البرنامج التدريبي', num: '02' },
    ];

export default function TraineeStepper({ step }: Props) {
    return (
        <div dir="rtl" className="mb-10 font-cairo w-full mt-10">
            <div className="flex flex-col sm:flex-row items-center justify-between gap-2  px-2">
                {steps.map((s, index) => {
                    const done = step > s.id;
                    const active = step === s.id;
                    const pending = step < s.id;

                    return (
                        <div key={s.id} className="flex flex-row items-center w-full sm:w-[45%] gap-y-4">

                            <div
                                className={cn(
                                    'flex flex-1 flex-row items-center gap-3 sm:gap-4 px-2 py-3 pb-4 transition-colors',
                                    active && 'border-b-[3px] border-primery-blue-600',
                                )}
                            >
                                <div
                                    className={cn(
                                        'flex h-11 w-11 shrink-0 items-center justify-center rounded-full text-sm font-bold transition-colors',
                                        done &&
                                        'bg-primery-blue-700 text-white shadow-sm border-2 border-primery-blue-700',
                                        active &&
                                        !done &&
                                        'border-2 border-primery-blue-600 bg-white text-primery-blue-600',
                                        pending && 'border-2 border-[#D1D5DB] bg-white text-[#9CA3AF]',
                                    )}
                                >
                                    {done ? (
                                        <Check className="h-5 w-5 text-white" strokeWidth={3} />
                                    ) : (
                                        s.num
                                    )}
                                </div>
                                <div className="flex-1 text-start">
                                    <p
                                        className={cn(
                                            'text-sm sm:text-base font-bold leading-tight',
                                            done && 'text-primery-blue-800',
                                            active && !done && 'text-primery-blue-600',
                                            pending && 'text-[#9CA3AF]',
                                        )}
                                    >
                                        {s.title}
                                    </p>
                                    <p
                                        className={cn(
                                            'mt-0.5 text-xs sm:text-sm leading-snug',
                                            done && 'text-[#6B7280]',
                                            active && !done && 'text-[#9CA3AF]',
                                            pending && 'text-[#C4C4C4]',
                                        )}
                                    >
                                        {s.subtitle}
                                    </p>
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
}
