import PersonalInfo from './PersonalInfo';
import Experience from './Experience';
import TrainingData from './TrainingData';
import TraineeStepper from './TraineeStepper';

import MainHeading from '@/components/heading/MainHeading';
import { Form } from '@/components/ui/form';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useMemo, useState } from 'react';
import { AddTraineeFormValues, AddTraineeSchema } from '../../schemas/AddTrainee/add-trainee-schema';
import { format } from 'date-fns';
import { TraineesDetails } from '../../types/configs.types';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import AddIcon from '@/components/icons/AddIcon';
import CancelPopup from '@/components/Popups/CancelPopup';
import SuccessPopup from '@/components/Popups/SuccessPopup';
import { useNavigate } from 'react-router-dom';

interface Props {
    trainee?: TraineesDetails | null;
}

type Step = 1 | 2;

const STEP1_FIELDS: (keyof AddTraineeFormValues)[] = [
    'name',
    'address',
    'id_number',
    'birth_date',
    'phone_number',
    'email',
    'education_degree',
    'university',
    'specialization',
    'graduation_year',
    'skills',
    'previous_experience',
    'degree_certificate',
];

export default function AddTraineeForm({ trainee }: Props) {
    const navigate = useNavigate();
    const [step, setStep] = useState<Step>(1);
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [showSuccessPopup, setShowSuccessPopup] = useState(false);
    const [showCancelPopup, setShowCancelPopup] = useState(false);

    const defaultValues = useMemo(
        () =>
            ({
                name: trainee?.name || '',
                address: trainee?.address || '',
                id_number: trainee?.id_number || '',
                birth_date: trainee?.birth_date ? new Date(trainee.birth_date) : undefined,
                phone_number: trainee?.phone_number || '',
                email: trainee?.email || '',
                education_degree: trainee?.education_degree || '',
                university: trainee?.university || '',
                specialization: trainee?.specialization || '',
                graduation_year: trainee?.graduation_year || '',
                skills: trainee?.skills || '',
                previous_experience: trainee?.previous_experience || '',
                degree_certificate: undefined,
                training_program: trainee?.program || '',
                direct_supervisor: trainee?.direct_supervisor || '',
                training_start_date: trainee?.start_date ? new Date(trainee.start_date) : undefined,
                training_end_date: trainee?.end_date ? new Date(trainee.end_date) : undefined,
                training_hours: trainee?.training_hours || '',
                weeks_count: trainee?.weeks_count || '',
                personal_image: undefined,
            }) as AddTraineeFormValues,
        [trainee],
    );

    const form = useForm<AddTraineeFormValues>({
        resolver: zodResolver(AddTraineeSchema),
        defaultValues,
    });

    const buildFormData = (data: AddTraineeFormValues) => {
        const fd = new FormData();
        const append = (key: string, value: unknown) => {
            if (value === undefined || value === null) return;
            if (value instanceof File) {
                fd.append(key, value);
            } else if (typeof value === 'string' && value.length === 0) {
                return;
            } else {
                fd.append(key, String(value));
            }
        };

        append('name', data.name);
        append('address', data.address);
        append('id_number', data.id_number);
        append('birth_date', format(data.birth_date, 'yyyy-MM-dd'));
        append('phone_number', data.phone_number);
        append('email', data.email);
        append('education_degree', data.education_degree);
        append('university', data.university);
        append('specialization', data.specialization);
        append('graduation_year', data.graduation_year);
        if (data.skills) append('skills', data.skills);
        if (data.previous_experience) append('previous_experience', data.previous_experience);

        append('training_program', data.training_program);
        append('direct_supervisor', data.direct_supervisor);
        append('training_start_date', format(data.training_start_date, 'yyyy-MM-dd'));
        append('training_end_date', format(data.training_end_date, 'yyyy-MM-dd'));
        append('training_hours', data.training_hours);
        append('weeks_count', data.weeks_count);

        if (data.personal_image instanceof File) {
            fd.append('personal_image', data.personal_image);
        }
        if (data.degree_certificate instanceof File) {
            fd.append('degree_certificate', data.degree_certificate);
        }

        return fd;
    };

    const onSubmit = async (data: AddTraineeFormValues) => {
        setLoading(true);
        setError(null);
        try {
            const body = buildFormData(data);
            await apiPost({
                endpoint: trainee ? endpoints.trainee.update + trainee.id : endpoints.trainee.create,
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                body: body as any,
                config: { headers: { 'Content-Type': 'multipart/form-data' } },
            });
            setShowSuccessPopup(true);
        } catch (err: unknown) {
            const error = err as { response?: { data?: { errors?: Record<string, string[]>; msg?: string } } };
            if (error.response?.data?.errors) {
                Object.entries(error.response.data.errors).forEach(([field, messages]) => {
                    form.setError(field as keyof AddTraineeFormValues, {
                        type: 'manual',
                        message: (messages as string[]).join(', '),
                    });
                });
            } else {
                let errorMessage = 'حدث خطأ أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';
                if (error.response?.data?.msg) {
                    errorMessage = error.response.data.msg;
                }
                setError(errorMessage);
            }
        } finally {
            setLoading(false);
        }
    };

    const goToNextStep = async () => {
        const valid = await form.trigger(STEP1_FIELDS);
        if (valid) {
            setStep(2);
        }
    };

    return (
        <>
            <Form {...form}>
                <form
                    className="mb-8"
                    onSubmit={(e) => {
                        e.preventDefault();
                        if (step !== 2) return;
                        void form.handleSubmit(onSubmit)(e);
                    }}
                >
                    {error && (
                        <div className="mb-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
                            <div className="flex justify-between items-center">
                                <span>{error}</span>
                                <button type="button" onClick={() => setError(null)} className="text-red-700 hover:text-red-900">
                                    ×
                                </button>
                            </div>
                        </div>
                    )}

                    <TraineeStepper step={step} />

                    {step === 1 && (
                        <div dir="rtl" className="font-cairo">
                            <MainHeading text="البيانات الشخصية" />
                            <PersonalInfo image={trainee?.personal_image} />
                            <MainHeading text="المؤهلات" />
                            <Experience image={trainee?.degree_certificate} />
                            <div className="flex flex-row flex-wrap justify-end gap-4 mt-8">
                                <SecondaryButton
                                    type="button"
                                    className="xl:px-[87px] xl:py-3 border bg-[#FFE9E9] border-[#E8EFF6] text-[#A21515] xl:font-semibold hover:bg-[#f5d6d6]"
                                    onClick={() => setShowCancelPopup(true)}
                                >
                                    إلغاء
                                </SecondaryButton>
                                <PrimaryButton type="button" className="xl:px-[91px] xl:py-3 xl:font-semibold" onClick={goToNextStep}>
                                    التالي
                                </PrimaryButton>
                            </div>
                        </div>
                    )}

                    {step === 2 && (
                        <div dir="rtl" className="font-cairo">
                            <MainHeading text="بيانات التدريب" />
                            <TrainingData personalImage={trainee?.personal_image} />
                            <div className="flex flex-row flex-wrap justify-between gap-4 mt-8 items-center">
                                <SecondaryButton
                                    type="button"
                                    className="xl:px-8 xl:py-3 border border-[#E8EFF6] text-primery-blue-700 bg-white-blue-50 xl:font-semibold"
                                    onClick={() => setStep(1)}
                                >
                                    السابق
                                </SecondaryButton>
                                <div className="flex flex-row items-center gap-4 justify-end">
                                    <SecondaryButton
                                        type="button"
                                        className="xl:px-[87px] xl:py-3 border bg-[#FFE9E9] border-[#E8EFF6] text-[#A21515] xl:font-semibold hover:bg-[#f5d6d6]"
                                        onClick={() => setShowCancelPopup(true)}
                                    >
                                        إلغاء
                                    </SecondaryButton>
                                    <PrimaryButton
                                        type="submit"
                                        className="xl:px-[91px] xl:py-3 xl:font-semibold gap-2 flex flex-row items-center"
                                        disabled={loading}
                                    >
                                        <AddIcon />
                                        {loading ? 'جاري الحفظ...' : 'حفظ'}
                                    </PrimaryButton>
                                </div>
                            </div>
                        </div>
                    )}
                </form>
            </Form>

            <CancelPopup
                open={showCancelPopup}
                onClickButton1={() => setShowCancelPopup(false)}
                onClickButton2={() => {
                    navigate('/human-resources/trainees');
                    setShowCancelPopup(false);
                }}
                text1="تم إلغاء العملية"
                text2="أنت على وشك إلغاء العملية دون إكمال البيانات. سيتم تجاهل جميع البيانات المدخلة، هل أنت متأكد؟"
                textButton1="إكمال الإدخال"
                textButton2="تأكيد الإلغاء"
            />
            <SuccessPopup
                text1={trainee ? 'تم تعديل بيانات المتدرب بنجاح' : 'تم إضافة المتدرب بنجاح'}
                text2={trainee ? 'تم حفظ التعديلات على بيانات المتدرب.' : 'تم تسجيل المتدرب الجديد في النظام.'}
                textButton1="العودة لقائمة المتدربين"
                textButton2={trainee ? 'العودة لقائمة المتدربين' : 'إضافة متدرب آخر'}
                open={showSuccessPopup}
                onAddAnother={() => {
                    setShowSuccessPopup(false);
                    form.reset(defaultValues);
                    setStep(1);
                }}
                onReturnToList={() => {
                    navigate('/human-resources/trainees');
                    setShowSuccessPopup(false);
                }}
            />
        </>
    );
}
