import { DateInputForm } from '@/components/forms/DateInputForm';
import TextInputForm from '@/components/forms/TextInputForm';

interface Props {
    image?: string | null;
}

export default function PersonalInfo({ image }: Props) {
    return (
        <div className="mb-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="flex flex-col gap-2">
                <TextInputForm name="name" label="اسم المتدرب" placeholder="ادخل اسم المتدرب" />
                <TextInputForm name="id_number" label="رقم الهوية" placeholder="ادخل رقم الهوية" />
                <TextInputForm
                    label="رقم الهاتف"
                    placeholder="ادخل رقم الهاتف"
                    className="[&>input]:text-end [&>input]:placeholder:text-end"
                    name="phone_number"
                    type="tel"
                />
            </div>
            <div className="flex flex-col gap-2">
                <TextInputForm name="address" label="العنوان" placeholder="ادخل العنوان" />
                <DateInputForm name="birth_date" label="تاريخ الميلاد" placeholder="ادخل تاريخ الميلاد" />
                <TextInputForm name="email" label="البريد الالكتروني" placeholder="ادخل البريد الالكتروني" />
            </div>
        </div>
    );
}
